#define LOGIN_PASSWORD "1122"

int verify_password() {
    char password[20];
    printf("Enter Password: ");
    scanf("%s", password);
    if (strcmp(password, LOGIN_PASSWORD) == 0) return 1;
    print_error("Invalid password.");
    return 0;
}

void print_table_product_row(int id, char name[], int stock) {
    printf("| %-4d | %-20s | %-10d |\n", id, name, stock);
}

